```

### Step 2: Create the Text Editor Component

```typescript
import { Component, Input } from '@angular/core';
import { MdEditorConfigService } from 'ngx-editor'; // Import the service

@Component({
  selector: 'app-text-editor',
  templateUrl: './text-editor.component.html'
})
export class TextEditorComponent {
  @Input() value: string = '';

  constructor(private mdEditorConfigService: MdEditorConfigService) {}

  onChange(value: string): void {
    this.mdEditorConfigService.updateContent(this.value);
  }
}
```

### Step 3: Display Content on Screen

In your template, include the text editor component inside a container where you'll add more components for each list.

```html
<div>
  <app-text-editor [(value)]="editorValue"></app-text-editor>
</div>

<!-- Add more divs for additional lists -->
<div *ngFor="let item of items">
  <app-list-item [list]="item"></app-list-item>
</div>
```

### Step 4: Manage Multiple Lists

Use Angular forms or arrays to manage different sections of the page dynamically.

#### Example Using FormArray

```typescript
import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { MdEditorConfigService } from 'ngx-editor'; // Import the service

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent implements OnInit {
  items = [
    { id: 0, title: '' },
    { id: 1, title: '' }
  ];

  formGroup: FormGroup;
  editorValue: string;

  constructor(
    private fb: FormBuilder,
    private mdEditorConfigService: MdEditorConfigService
  ) {}

  ngOnInit(): void {
    this.formGroup = this.fb.group({
      lists: this.items.map(item => ({ title: '' }))
    });

    this.editorValue = JSON.stringify(this.formGroup.value);
  }

  onChange(index: number, newValue: string): void {
    const updatedLists = [...this.formGroup.get('lists') as any[]];
    updatedLists[index].title = newValue;
    this.formGroup.setValue(updatedLists);

    this.editorValue = JSON.stringify(this.formGroup.value);
  }
}
```

